  "A feature edit does not identify a record of the current inputs. Generate again; if it continues, save a Session for investigation.": "Редагування ознаки не визначає запис поточних вхідних даних. Створіть діаграму знову; якщо проблема повторюється, збережіть сеанс для дослідження.",
  "A figure that splits records over several rows draws no comparisons. Remove the comparison inputs, or reset canvas.linear.wrap_length under Preserved session settings.": "На діаграмі, що розбиває записи на кілька рядків, порівняння не відображаються. Вилучіть вхідні дані порівняння або скиньте canvas.linear.wrap_length у розділі «Збережені налаштування сеансу».",
