  "A table row names another displayed record in this column. Swap the query and subject columns of the table, or assign the table to the pair it describes.": "Рядок таблиці вказує в цьому стовпці на інший показаний запис. Поміняйте місцями стовпці query і subject таблиці або призначте таблицю парі, яку вона описує.",
