  "Adding a Depth file, or a series while one is loaded, turns Show Depth on, and removing the last Depth file or the File that holds it turns it off; turning it off hides the drawn Depth track at once. A changed Legend title clears a Legend tab rename of the old title at once. The rest, and a Depth track from changed files, applies on Generate": "Додавання файлу глибини або серії, коли файл глибини вже завантажено, вмикає «Показати глибину», а вилучення останнього файлу глибини або картки файлу, яка його містить, вимикає це налаштування; вимкнення одразу приховує намальовану доріжку глибини. Зміна заголовка легенди одразу скасовує перейменування старого заголовка, виконане на вкладці «Легенда». Решта, а також доріжка глибини зі змінених файлів, застосовується під час створення",
