  "Applies on Generate": "Застосовується під час створення",
  "Applies on Generate, except turning a GC content, GC skew or Depth row on or off, removing one, and Use custom stack, which apply at once; turning on a row added since the last Generate, a row that was off when the Session was loaded, or a Depth row after a Depth file change apply on Generate, and so does Use custom stack after a Session load (except turned off on a Linear Result drawn with it) or while the Region Annotation sets differ from those of the Result, with every track it would hide or show": "Застосовується під час створення. Вмикання й вимикання рядка вмісту GC, GC skew або глибини, вилучення такого рядка та зміна налаштування «Використовувати власний стек» застосовуються одразу, за наведеними далі винятками. Під час створення застосовується вмикання рядка, доданого після останнього створення, рядка, який був вимкнений під час завантаження сеансу, або рядка глибини після зміни файлу глибини. Зміна налаштування «Використовувати власний стек» також застосовується під час створення після завантаження сеансу (крім вимкнення цього налаштування для результату лінійної діаграми, намальованого з власним стеком) або коли набори анотацій ділянок відрізняються від наборів у результаті; це стосується й усіх доріжок, які ця зміна приховала б або показала",
  "Applies the live circular track arrangement used while Custom Track Slots is off. Custom Track Slots inherit this preset when enabled.": "Застосовує поточне розташування доріжок кільцевої діаграми, яке діє, коли «Власні слоти доріжок» вимкнено. Коли «Власні слоти доріжок» увімкнено, вони успадковують цей пресет.",
  "Applies to SVG and Interactive SVG exports, not to Generate.": "Застосовується до експорту SVG та інтерактивного SVG, а не до створення.",
