  "Auto Reflow failed. Current diagram is kept.": "Автоматичне перекомпонування не вдалося. Поточну діаграму збережено.",
  "Auto embeds labels that fit and routes the rest externally. Embedded Only drops labels that need external placement. External Only keeps labels outside feature bodies.": "«Авто» вбудовує підписи, які вміщуються, а решту виносить назовні. «Лише вбудовані» відкидає підписи, яким потрібне зовнішнє розміщення. «Лише зовнішні» залишає підписи поза межами ознак.",
  "Auto follows the track layout (Above or Features on axis: labels above; Below: labels below). Above Feature draws labels above features (and below negative-strand features when Separate Strands is on).": "«Авто» відповідає макету доріжок («Вище» або «Ознаки на осі»: підписи вище; «Нижче»: підписи нижче). «Над ознакою» малює підписи над ознаками (а коли ввімкнено «Розділяти за ланцюгами» — під ознаками на ланцюзі −).",
  "Auto hides these fields throughout the diagram": "«Авто» приховує ці поля в усій діаграмі",
  "Auto makes the CDSs that share a locus identifier one unit and every other CDS a unit of its own. CDS makes each CDS a unit. Locus makes each locus a unit and requires a locus identifier, such as /locus_tag, on every CDS.": "«Авто» об’єднує CDS зі спільним ідентифікатором локусу в одну одиницю, а кожну іншу CDS робить окремою одиницею. «CDS» робить одиницею кожну CDS. «Локус» робить одиницею кожен локус і вимагає наявності ідентифікатора локусу, наприклад /locus_tag, у кожній CDS.",
  "Auto runs threaded LOSAT when this browser supports it, and serial LOSAT otherwise. LOSATN task dc-megablast needs threaded LOSAT.": "«Авто» запускає багатопотоковий LOSAT, якщо цей браузер його підтримує, а в іншому разі послідовний LOSAT. Для задачі LOSATN dc-megablast потрібен багатопотоковий LOSAT.",
  "Auto shows these fields throughout the diagram": "«Авто» показує ці поля в усій діаграмі",
  "Auto will hide these fields throughout the diagram on the next successful Generate": "«Авто» приховає ці поля в усій діаграмі під час наступного успішного створення",
  "Auto will show these fields throughout the diagram on the next successful Generate": "«Авто» покаже ці поля в усій діаграмі під час наступного успішного створення",
