  "Base colors for features, comparison tracks, and collinear blocks. The selected palette supplies unchanged colors; colors you edit override it; when you change the palette, a dialog asks whether to keep them.": "Базові кольори ознак, доріжок порівняння та колінеарних блоків. Вибрана палітра задає кольори, яких ви не змінювали; змінені вами кольори перевизначають її; коли ви змінюєте палітру, діалогове вікно запитує, чи залишити їх.",
  "Base text shown in the diagram legend. Leave blank to use the auto label shown here; two-color tracks add (+) and (-).": "Основний текст, що показується в легенді діаграми. Залиште порожнім, щоб використати автоматичний підпис, показаний тут; для двоколірних доріжок додаються позначення (+) і (-).",
