  "Changes this legend swatch only. The plot keeps the color set in Settings.": "Змінює лише цей зразок кольору в легенді. Графік зберігає колір, заданий у налаштуваннях.",
  "Change…": "Змінити…",
  "Changing \"{setting}\" to \"{value}\" removes the lane for {count} feature you placed manually.": "Зміна налаштування «{setting}» на значення «{value}» вилучає рівень для {count} ознаки, розміщеної вручну.",
  "Changing \"{setting}\" to \"{value}\" removes the lane for {count} features you placed manually.": {"one": "Зміна налаштування «{setting}» на значення «{value}» вилучає рівень для {count} ознаки, розміщеної вручну.", "few": "Зміна налаштування «{setting}» на значення «{value}» вилучає рівень для {count} ознак, розміщених вручну.", "many": "Зміна налаштування «{setting}» на значення «{value}» вилучає рівень для {count} ознак, розміщених вручну.", "other": "Зміна налаштування «{setting}» на значення «{value}» вилучає рівень для {count} ознаки, розміщеної вручну."},
  "Check the Python group syntax.": "Перевірте синтаксис груп Python.",
  "Check the character range.": "Перевірте діапазон символів.",
