  "Checking color rules…": "Перевірка правил кольору…",
  "Checking color rule…": "Перевірка правила кольору…",
  "Choose BLAST TSV for {name}": "Обрати TSV BLAST для пари {name}",
  "Choose LOSATN or TLOSATX for comparison rings.": "Оберіть LOSATN або TLOSATX для кілець порівняння.",
  "Choose On to show it.": "Оберіть «Увімкнено», щоб показати його.",
