  "Choose a fix": "Обрати виправлення",
  "Choose a gbdraw Session file.": "Оберіть файл сеансу gbdraw.",
  "Choose a gene": "Обрати ген",
  "Choose a nucleotide, protein, or translated nucleotide search. LOSATP settings are preserved while another mode is active.": "Оберіть нуклеотидний або білковий пошук чи пошук із трансляцією нуклеотидних послідовностей. Налаштування LOSATP зберігаються, поки активний інший режим.",
  "Choose a readable TrueType or OpenType font file (.ttf, .otf, .ttc, .otc) that names its font family.": "Оберіть придатний для читання файл шрифту TrueType або OpenType (.ttf, .otf, .ttc, .otc), у якому вказано сімейство шрифтів.",
