  "Choosing \"{setting}\" removes the lane for {count} features you placed manually.": {"one": "Вибір варіанта «{setting}» вилучає рівень для {count} ознаки, розміщеної вручну.", "few": "Вибір варіанта «{setting}» вилучає рівень для {count} ознак, розміщених вручну.", "many": "Вибір варіанта «{setting}» вилучає рівень для {count} ознак, розміщених вручну.", "other": "Вибір варіанта «{setting}» вилучає рівень для {count} ознаки, розміщеної вручну."},
