  "Custom Track Slots no longer read this field. Use slot-level radius, width, inner_gap_px, outer_gap_px, side, and z fields.": "Власні слоти доріжок більше не зчитують це поле. Використовуйте поля radius, width, inner_gap_px, outer_gap_px, side і z на рівні слота.",
  "Custom position": "Власна позиція",
  "Custom stack Depth rows control rendering. Disable the custom stack to change this simple control.": "Відображенням керують рядки глибини власного стека. Вимкніть власний стек, щоб змінити цей простий елемент керування.",
  "Custom stack geometry is active. Use each Depth row width, or Reset to copy this value into the stack.": "Активна геометрія власного стека. Налаштуйте ширину в кожному рядку глибини або натисніть «Скинути», щоб скопіювати це значення в стек.",
  "Custom stack geometry is active. Use the Dinucleotide content row radius, or Reset to copy this value into the stack.": "Активна геометрія власного стека. Налаштуйте радіус у рядку «Вміст динуклеотидів» або натисніть «Скинути», щоб скопіювати це значення в стек.",
  "Custom stack geometry is active. Use the Dinucleotide content row width, or Reset to copy this value into the stack.": "Активна геометрія власного стека. Налаштуйте ширину в рядку «Вміст динуклеотидів» або натисніть «Скинути», щоб скопіювати це значення в стек.",
  "Custom stack geometry is active. Use the Dinucleotide skew row radius, or Reset to copy this value into the stack.": "Активна геометрія власного стека. Налаштуйте радіус у рядку «Динуклеотидний skew» або натисніть «Скинути», щоб скопіювати це значення в стек.",
  "Custom stack geometry is active. Use the Dinucleotide skew row width, or Reset to copy this value into the stack.": "Активна геометрія власного стека. Налаштуйте ширину в рядку «Динуклеотидний skew» або натисніть «Скинути», щоб скопіювати це значення в стек.",
  "Custom stack geometry is active. Use the Features row width, or Reset to copy this value into the stack.": "Активна геометрія власного стека. Налаштуйте ширину в рядку «Ознаки» або натисніть «Скинути», щоб скопіювати це значення в стек.",
  "Custom stack is saved but inactive; generation uses the simple track controls.": "Власний стек збережено, але він неактивний; під час створення використовуються прості елементи керування доріжками.",
