  "Depth series {series} stay empty, and Generate will ask for a file or their removal.": {"one": "Серії глибини {series} залишаються порожніми, а під час створення вам запропонують додати файл або вилучити ці серії.", "few": "Серії глибини {series} залишаються порожніми, а під час створення вам запропонують додати файл або вилучити ці серії.", "many": "Серії глибини {series} залишаються порожніми, а під час створення вам запропонують додати файл або вилучити ці серії.", "other": "Серії глибини {series} залишаються порожніми, а під час створення вам запропонують додати файл або вилучити ці серії."},
