  "Drag a record, legend, title, or Linear scale to reposition": "Перетягніть запис, легенду, заголовок або масштабний відрізок лінійної діаграми, щоб змінити розташування",
  "Drag to reorder, or press the Up or Down arrow": "Перетягніть, щоб змінити порядок, або натисніть стрілку вгору чи вниз",
  "Drag to resize": "Перетягніть, щоб змінити розмір",
  "Draw a Linear map.": "Намалюйте лінійну діаграму.",
  "Draw all sequences at the same displayed length. Hides the length bar.": "Малює всі послідовності однакової відображуваної довжини. Приховує масштабний відрізок.",
  "Draw one circular pairwise comparison ring per uploaded BLAST outfmt 6/7 file or browser LOSATN/TLOSATX comparison sequence file (FASTA, GenBank, or DDBJ). Reverse BLAST coordinates are shown as reverse hits, not origin-spanning hits.": "Малює одне кільце попарного порівняння на кожен переданий файл BLAST outfmt 6/7 або файл порівнюваної послідовності для LOSATN/TLOSATX у браузері (FASTA, GenBank або DDBJ). Зворотні координати BLAST показуються як зворотні hit, а не як hit, що перетинають початок кільця.",
  "Draw records": "Малювати записи",
  "Draw this record": "Малювати цей запис",
  "Draws each label that the label priority names from the gene qualifier in italics, also after its text is edited. Other labels stay upright.": "Малює курсивом кожен підпис, який згідно з пріоритетом підписів береться з кваліфікатора gene, також після редагування його тексту. Інші підписи залишаються прямими.",
  "Duplicate": "Дублювати",
  "Duplicate set": "Дублювати набір",
