  "Edit specific color rule": "Редагувати окреме правило кольору",
  "Edit the explicit circular stack. Opening or closing this panel does not enable or alter the stack. Rows above Axis render outside and rows below Axis render inside.": "Редагуйте явний стек доріжок кільцевої діаграми. Відкриття чи закриття цієї панелі не вмикає й не змінює стек. Рядки над рядком «Вісь» малюються зовні, а рядки під ним — всередині.",
  "Edit the explicit linear track stack. Opening or closing this panel does not enable or alter the stack. Arrows reorder within the current side; Row actions move rows across the boundary.": "Редагуйте явний стек доріжок лінійної діаграми. Відкриття чи закриття цієї панелі не вмикає й не змінює стек. Стрілки змінюють порядок у межах поточного боку; «Дії з рядком» переміщують рядки через межу.",
  "Edit this record in its File card in the sidebar.": "Редагуйте цей запис у картці файлу на бічній панелі.",
