  "Fix the identity colour scale so figures with different thresholds share colours and Legend labels. Leave the minimum blank to colour from the minimum identity to 100%.": "Фіксує колірну шкалу ідентичності, щоб діаграми з різними порогами мали однакові кольори й підписи в легенді. Залиште мінімум порожнім, щоб застосувати колірну шкалу від мінімальної ідентичності до 100%.",
