  "Font size for feature labels.": "Розмір шрифту підписів ознак.",
  "Font size for record-label text (species/strain in circular; organism/replicon/accession/length stack in linear).": "Розмір шрифту тексту підписів записів (вид/штам у кільцевій діаграмі; стек організм/реплікон/реєстраційний номер/довжина в лінійній).",
  "Font size for ruler tick labels, including rulers drawn on record axes.": "Розмір шрифту підписів поділок лінійки, зокрема лінійок на осях записів.",
  "Font size for the circular shared plot title. Only used when the title position is Top or Bottom.": "Розмір шрифту спільного заголовка кільцевої діаграми. Використовується, лише коли позиція заголовка — «Угорі» або «Унизу».",
  "Font size for the legend text.": "Розмір шрифту для тексту легенди.",
