  "Font size for the simple bar scale label.": "Розмір шрифту підпису простого масштабного відрізка.",
  "Font size for this track's depth tick labels. Leave blank for auto.": "Розмір шрифту підписів поділок глибини для цієї доріжки. Залиште порожнім для автоматичного значення.",
  "Font {family} could not be prepared for the PDF. Its text is drawn in {substitute}.": "Не вдалося підготувати шрифт {family} для PDF. Його текст намальовано шрифтом {substitute}.",
  "Font {family} is not embedded in the PDF: its license (OS/2 fsType) does not allow embedding. Its text is drawn in {substitute}.": "Шрифт {family} не вбудовано в PDF: його ліцензія (OS/2 fsType) не дозволяє вбудовування. Його текст намальовано шрифтом {substitute}.",
  "Font {family} is not embedded: its license (OS/2 fsType) does not allow embedding. The SVG shows it only where {family} is installed.": "Шрифт {family} не вбудовано: його ліцензія (OS/2 fsType) не дозволяє вбудовування. SVG показує його лише там, де встановлено шрифт {family}.",
  "Fonts loaded in this page could not be prepared again for drawing. Load them again in Font, or choose another font.": "Шрифти, завантажені на цій сторінці, не вдалося знову підготувати для малювання. Завантажте їх знову в розділі «Шрифт» або оберіть інший шрифт.",
