  "Group path ID": "ID шляху групи",
  "Group paths": "Шляхи групи",
  "Halo": "Ореол",
  "Halo draws a white outline around the letters of each label with a leader, so leaders behind them are cut away. Box draws a white box behind the letters. None draws neither.": "«Ореол» малює білий контур навколо літер кожного підпису з виноскою, тож виноски позаду літер обрізаються. «Рамка» малює білий прямокутник позаду літер. «Немає» не малює ані контуру, ані прямокутника.",
  "Hatch": "Штриховка",
  "Head Length Ratio": "Відношення довжини наконечника",
  "Head length and shaft width apply to Arrow features and remain available even when no feature currently uses that rendering.": "Довжина наконечника та ширина тіла стрілки застосовуються до ознак у вигляді стрілки й залишаються доступними, навіть якщо жодна ознака наразі не використовує це відображення.",
  "Head length divided by the full rendered feature thickness. Leave blank for Auto. Auto starts from the mode-specific default and lengthens the head as the shaft narrows.": "Довжина наконечника, поділена на повну відображену товщину ознаки. Залиште порожнім для автоматичного значення. Автоматичне значення спершу дорівнює типовому для режиму, а зі звуженням тіла стрілки наконечник подовжується.",
  "Height": "Висота",
  "Height must be a positive number of pixels (px optional).": "Висота має бути додатним числом пікселів (px необов’язково).",
  "Height of the feature blocks.": "Висота блоків ознак.",
  "Height of the linear GC content and GC skew tracks. Applies to whichever of those tracks are enabled when the diagram is generated.": "Висота доріжок вмісту GC і GC skew лінійної діаграми. Застосовується до тих із цих доріжок, які ввімкнено під час створення діаграми.",
  "Height of this linear depth coverage track in px. Leave blank for auto.": "Висота цієї доріжки глибини лінійної діаграми в px. Залиште порожнім для автоматичного значення.",
