  "Highlights render automatically behind the feature track. Line, Bracket, and Band render in a separate annotation lane. Custom Track Slots can override this automatic placement.": "«Виділення» автоматично малюються позаду доріжки ознак. «Лінія», «Дужка» та «Смуга» малюються на окремому рівні анотацій. «Власні слоти доріжок» можуть перевизначити це автоматичне розміщення.",
  "Horizontal": "Горизонтальне",
