  "If you save a .gbdraw-session.json.gz and load it back in the web app, the uploaded inputs, results, and LOSAT cache are restored from the compressed JSON; these TSV files do not need to be saved separately for session restore.": "Якщо зберегти .gbdraw-session.json.gz і завантажити його назад у вебзастосунку, передані вхідні файли, результати та кеш LOSAT буде відновлено зі стисненого JSON; ці файли TSV не потрібно окремо зберігати для відновлення сеансу.",
  "If you use gbdraw in your research, please cite the preprint:": "Якщо ви використовуєте gbdraw у своєму дослідженні, будь ласка, цитуйте препринт:",
  "Ignored annotation table columns: {columns}. These columns are not saved in Sessions or TSV re-export.": "Проігноровані стовпці таблиці анотацій: {columns}. Ці стовпці не зберігаються в сеансах і під час повторного експорту TSV.",
