  "In one record, this selector names features that start at different bases. Use a selector that names one feature, such as locus_tag=<tag>.": "В одному записі цей селектор вказує на ознаки, що починаються в різних нуклеотидних позиціях. Використайте селектор, що вказує на одну ознаку, наприклад locus_tag=<tag>.",
