  "Labels are set to \"None\" (\"Show Labels\" or \"Label Mode\"), so only a feature with Label visibility \"On\" has one.": "Для підписів вибрано «Немає» («Показати підписи» або «Режим підписів»), тому підпис має лише ознака, для якої параметр «Видимість підпису» має значення «Увімкнено».",
