  "Legend: entries {items} had a color the app does not accept and were dropped.": {"one": "Легенда: елементи {items} мали колір, який застосунок не приймає, їх відкинуто.", "few": "Легенда: елементи {items} мали колір, який застосунок не приймає, їх відкинуто.", "many": "Легенда: елементи {items} мали колір, який застосунок не приймає, їх відкинуто.", "other": "Легенда: елементи {items} мали колір, який застосунок не приймає, їх відкинуто."},
  "Legend: entries {items} repeat an earlier entry of their list and were dropped.": {"one": "Легенда: елементи {items} повторюють попередній елемент свого списку, їх відкинуто.", "few": "Легенда: елементи {items} повторюють попередній елемент свого списку, їх відкинуто.", "many": "Легенда: елементи {items} повторюють попередній елемент свого списку, їх відкинуто.", "other": "Легенда: елементи {items} повторюють попередній елемент свого списку, їх відкинуто."},
  "Legend: entry {items} had a color the app does not accept and was dropped.": "Легенда: елемент {items} мав колір, який застосунок не приймає, його відкинуто.",
  "Legend: entry {items} repeats an earlier entry of its list and was dropped.": "Легенда: елемент {items} повторює попередній елемент свого списку, його відкинуто.",
  "Legend: the color edit stored under \"{label}\" ({path}) moves to the row \"{used}\", which has an edit of its own; that edit is used and this one was dropped.": "Легенда: редагування кольору, збережене під назвою «{label}» ({path}), переходить до рядка «{used}», який уже має власне редагування; використано те редагування, а це відкинуто.",
  "Legend: the color edit stored under \"{label}\" ({path}) sets the row \"{used}\", which a later edit also sets; the later edit is used and this one was dropped.": "Легенда: редагування кольору, збережене під назвою «{label}» ({path}), задає рядок «{used}», що його також задає пізніше редагування; використано пізніше редагування, а це відкинуто.",
  "Legend: the entry stored under \"{label}\" ({path}) moves to the row \"{used}\", which has an entry of its own; that entry is used and this one was dropped.": "Легенда: елемент, збережений під назвою «{label}» ({path}), переходить до рядка «{used}», який уже має власний елемент; використано той елемент, а цей відкинуто.",
  "Legend: the entry stored under \"{label}\" ({path}) sets the row \"{used}\", which a later edit also sets; the later edit is used and this one was dropped.": "Легенда: елемент, збережений під назвою «{label}» ({path}), задає рядок «{used}», що його також задає пізніше редагування; використано пізніше редагування, а цей елемент відкинуто.",
  "Legend: the position \"{stored}\" ({path}) is not one of its mode's positions; it is not used.": "Легенда: позиція «{stored}» ({path}) не належить до позицій її режиму; її не використано.",
  "Legend: the position \"{stored}\" ({path}) is not one of its mode's positions; {used} is used.": "Легенда: позиція «{stored}» ({path}) не належить до позицій її режиму; використано {used}.",
  "Legend: the stroke edit stored under \"{label}\" ({path}) moves to the row \"{used}\", which has an edit of its own; that edit is used and this one was dropped.": "Легенда: редагування контуру, збережене під назвою «{label}» ({path}), переходить до рядка «{used}», який уже має власне редагування; використано те редагування, а це відкинуто.",
  "Legend: the stroke edit stored under \"{label}\" ({path}) sets the row \"{used}\", which a later edit also sets; the later edit is used and this one was dropped.": "Легенда: редагування контуру, збережене під назвою «{label}» ({path}), задає рядок «{used}», що його також задає пізніше редагування; використано пізніше редагування, а це відкинуто.",
