  "Linear vertical spacing after the track, in pixels (px optional; nonnegative). Leave blank for the automatic spacing.": "Вертикальна відстань після доріжки лінійної діаграми в пікселях (px необов’язково; значення невід’ємне). Залиште порожнім для автоматичної відстані.",
