  "List all 12 standard BLAST outfmt 6 fields in the \"# Fields:\" line, or remove the line so that the first 12 columns are read in the standard order.": "Перелічіть усі 12 стандартних полів BLAST outfmt 6 у рядку «# Fields:» або вилучіть цей рядок, щоб перші 12 стовпців читалися в стандартному порядку.",
  "Live edit": "Редагування наживо",
  "Live edit applying: geometry is being updated. Direct edits already applied are kept.": "Застосування редагування наживо: оновлюється геометрія. Прямі редагування, що вже застосовано, зберігаються.",
  "Live edit failed: direct edits already applied are kept; geometry may still need updating.": "Помилка редагування наживо: уже застосовані прямі редагування збережено; геометрію, можливо, ще потрібно оновити.",
  "Live edit. Showing a track applies on Generate if the Result did not draw it when its Session was loaded; after a Depth file or series change, or a change of the records the Depth files map to; for a custom stack row added since the last Generate or a stack the last Generate could not build; and, with a Circular custom track stack or Circular track widths or radii, for Hide GC Content and Hide GC Skew turned off": "Редагування наживо. Показ доріжки застосовується під час створення, якщо результат не містив її, коли завантажували сеанс; після зміни файлу або серії глибини чи зміни записів, з якими пов’язано файли глибини; для рядка власного стека, доданого після останнього створення, або стека, який не вдалося побудувати під час останнього створення; а також за використання власного стека доріжок кільцевої діаграми або ширин чи радіусів доріжок кільцевої діаграми, коли знято позначки «Приховати вміст GC» і «Приховати GC skew»",
  "Live edit: feature color, label text, and visibility update the current Result; geometry may rerender automatically.": "Редагування наживо: колір ознаки, текст підпису та видимість оновлюють поточний результат; геометрія може автоматично перемальовуватися.",
  "Live edit: legend text, order, stroke, and removal update the current Result.": "Редагування наживо: текст легенди, порядок, контур і вилучення оновлюють поточний результат.",
  "Live edit; the position applies on Generate after the Multi-Record Canvas change": "Редагування наживо; позиція застосовується під час створення після зміни налаштування «Полотно з кількома записами»",
