  "Load with {substitutes}": "Завантажити, використавши {substitutes}",
  "Load with {substitutes}: the Session opens and its text is drawn in {substitutes}, the nearest available font.": "Завантажити, використавши {substitutes}: сеанс відкриється, а його текст буде намальовано шрифтом {substitutes} — найближчим доступним.",
  "Load with {substitutes}: the Session opens and its text is drawn in {substitutes}, the nearest available fonts.": {"one": "Завантажити, використавши {substitutes}: сеанс відкриється, а його текст буде намальовано шрифтами {substitutes} — найближчими доступними.", "few": "Завантажити, використавши {substitutes}: сеанс відкриється, а його текст буде намальовано шрифтами {substitutes} — найближчими доступними.", "many": "Завантажити, використавши {substitutes}: сеанс відкриється, а його текст буде намальовано шрифтами {substitutes} — найближчими доступними.", "other": "Завантажити, використавши {substitutes}: сеанс відкриється, а його текст буде намальовано шрифтами {substitutes} — найближчими доступними."},
  "Loaded records: {count}.": "Кількість завантажених записів: {count}.",
  "Loaded {count} row.": "Завантажено {count} рядок.",
  "Loaded {count} rows.": {"one": "Завантажено {count} рядок.", "few": "Завантажено {count} рядки.", "many": "Завантажено {count} рядків.", "other": "Завантажено {count} рядка."},
  "Loading a Session replaces the current settings and Results and clears Undo history.": "Завантаження сеансу замінює поточні налаштування й результати та очищає історію скасування.",
  "Loading records...": "Завантаження записів…",
  "Loading session. Retry after loading finishes.": "Завантаження сеансу. Повторіть після завершення.",
  "Loading session…": "Завантаження сеансу…",
  "Loading the font…": "Завантаження шрифту…",
