  "Override the center-label reserved radius in px. Lower values let inside tracks move closer to the center and may overlap the label.": "Перевизначає радіус, зарезервований для центрального підпису, в px. Менші значення дозволяють внутрішнім доріжкам наближатися до центру, через що доріжки можуть перекривати підпис.",
