  "Raw LOSATP search limit per query protein (--max-target-seqs). In a within-record search the query protein itself counts as one target. Leave blank for an unbounded search, the default. Changing this value requires matching raw search results. Each mode remembers its own hit limits.": "Обмеження необробленого пошуку LOSATP для кожного білка query (--max-target-seqs). У пошуку в межах запису сам білок query враховується як одна ціль. Залиште порожнім для необмеженого пошуку (типово). Зміна цього значення потребує відповідних необроблених результатів пошуку. Кожен режим запам’ятовує власні обмеження hit.",
