  "Reverse-complements the record when this feature is on the − strand.": "Застосовує до запису зворотний комплемент, коли ця ознака лежить на ланцюзі −.",
  "Reverses {records} so all {count} chosen features point left.": {"one": "Розвертає: {records}. Усі вибрані ознаки ({count}) будуть спрямовані ліворуч.", "few": "Розвертає: {records}. Усі вибрані ознаки ({count}) будуть спрямовані ліворуч.", "many": "Розвертає: {records}. Усі вибрані ознаки ({count}) будуть спрямовані ліворуч.", "other": "Розвертає: {records}. Усі вибрані ознаки ({count}) будуть спрямовані ліворуч."},
  "Reverses {records} so all {count} chosen features point right.": {"one": "Розвертає: {records}. Усі вибрані ознаки ({count}) будуть спрямовані праворуч.", "few": "Розвертає: {records}. Усі вибрані ознаки ({count}) будуть спрямовані праворуч.", "many": "Розвертає: {records}. Усі вибрані ознаки ({count}) будуть спрямовані праворуч.", "other": "Розвертає: {records}. Усі вибрані ознаки ({count}) будуть спрямовані праворуч."},
  "Reverses {records} so the chosen feature points left.": "Розвертає: {records}. Вибрана ознака буде спрямована ліворуч.",
  "Reverses {records} so the chosen feature points right.": "Розвертає: {records}. Вибрана ознака буде спрямована праворуч.",
  "Reverses {records}.": "Розвертає: {records}.",
  "Reversing flips a whole record with its labels and ribbons. Strands in the data (+/−) do not change.": "Розвертання перевертає весь запис разом з його підписами та стрічками. Ланцюги в даних (+/−) не змінюються.",
  "Revert": "Відкотити",
  "Review alignment": "Перевірка вирівнювання",
  "Review alignment options for the selected exact feature": "Перевірити параметри вирівнювання для вибраної референсної ознаки",
  "Review alignment options for this exact feature": "Перевірити параметри вирівнювання для цієї самої ознаки",
  "Review alignment options…": "Перевірити параметри вирівнювання…",
  "Review the updated preview and Apply again.": "Перевірте оновлений попередній перегляд і знову натисніть «Застосувати».",
