  "Wait for the current alignment operation to finish.": "Дочекайтеся завершення поточної операції вирівнювання.",
  "Wait for the record list to finish loading, then retry.": "Дочекайтеся завершення завантаження списку записів і спробуйте ще раз.",
  "Weight": "Накреслення",
  "When TLOSATX needs a translation table that a record lacks, Gencode required appears beside its file name.": "Якщо для TLOSATX потрібен генетичний код, якого запис не має, поруч із назвою файлу з’являється «Потрібен генетичний код».",
  "When enabled, feature clicks show Details, Qualifiers, and Sequence tabs. Disable for the compact edit-only popup.": "Якщо увімкнено, після натискання на ознаку показуються вкладки «Подробиці», «Кваліфікатори» та «Послідовність». Вимкніть, щоб отримати компактне спливне вікно лише для редагування.",
  "When off, changing the palette only updates the swatches. The preview keeps the current palette until you click Generate Diagram.": "Коли вимкнено, зміна палітри оновлює лише зразки кольору. Попередній перегляд зберігає поточну палітру, доки ви не натиснете «Створити діаграму».",
  "White background": "Білий фон",
  "Whitelist": "Білий список",
  "Whitelist File": "Файл білого списку",
  "Whole record": "Увесь запис",
  "Width": "Ширина",
  "Width and Radius: px or ×R": "Ширина і радіус: px або ×R",
  "Width and Radius: px or ×R, where R is the base circular radius. Paste 20px or 65% (0.65 ×R). Changing units keeps the number. Blank means Auto; its unit selection is for the next input only.": "Ширина і радіус: px або ×R, де R — базовий радіус кільцевої діаграми. Вставте 20px або 65% (0.65 ×R). Зміна одиниць зберігає число. Порожнє значення означає «Авто»; вибір одиниці для нього стосується лише наступного введення.",
  "Width must be a number greater than 0, in px or ×R.": "Ширина має бути числом, більшим за 0, у px або ×R.",
  "Width of the lines representing introns.": "Ширина ліній, що позначають інтрони.",
  "Width of the main axis line.": "Ширина основної лінії осі.",
  "Width of the outline for feature blocks.": "Ширина контуру блоків ознак.",
  "Window": "Вікно",
  "Window size for GC content/skew. Default: 1kb (<1Mb), 10kb (<10Mb), 100kb (>=10Mb).": "Розмір вікна для вмісту GC / skew. Типово: 1kb (<1Mb), 10kb (<10Mb), 100kb (>=10Mb).",
  "Window size for depth aggregation. Blank: a tenth of the GC window, at least 100 bp.": "Розмір вікна для агрегування глибини. Порожнє значення: одна десята вікна GC, щонайменше 100 bp.",
  "With \"Label Rendering\" = \"Embedded Only\", a label is drawn only when it fits inside its feature.": "Якщо параметр «Відображення підписів» має значення «Лише вбудовані», підпис малюється лише тоді, коли вміщується всередині своєї ознаки.",
  "Yes": "Так",
  "Your custom track stack has {count} GC content track. Hiding GC content turns that track off.": "Ваш власний стек доріжок містить {count} доріжку вмісту GC. Якщо приховати вміст GC, цю доріжку буде вимкнено.",
  "Your custom track stack has {count} GC content tracks. Hiding GC content turns those tracks off.": {"one": "Ваш власний стек доріжок містить {count} доріжку вмісту GC. Якщо приховати вміст GC, ці доріжки буде вимкнено.", "few": "Ваш власний стек доріжок містить {count} доріжки вмісту GC. Якщо приховати вміст GC, ці доріжки буде вимкнено.", "many": "Ваш власний стек доріжок містить {count} доріжок вмісту GC. Якщо приховати вміст GC, ці доріжки буде вимкнено.", "other": "Ваш власний стек доріжок містить {count} доріжки вмісту GC. Якщо приховати вміст GC, ці доріжки буде вимкнено."},
  "Your custom track stack has {count} GC skew track. Hiding GC skew turns that track off.": "Ваш власний стек доріжок містить {count} доріжку GC skew. Якщо приховати GC skew, цю доріжку буде вимкнено.",
  "Your custom track stack has {count} GC skew tracks. Hiding GC skew turns those tracks off.": {"one": "Ваш власний стек доріжок містить {count} доріжку GC skew. Якщо приховати GC skew, ці доріжки буде вимкнено.", "few": "Ваш власний стек доріжок містить {count} доріжки GC skew. Якщо приховати GC skew, ці доріжки буде вимкнено.", "many": "Ваш власний стек доріжок містить {count} доріжок GC skew. Якщо приховати GC skew, ці доріжки буде вимкнено.", "other": "Ваш власний стек доріжок містить {count} доріжки GC skew. Якщо приховати GC skew, ці доріжки буде вимкнено."},
  "Zero-based non-negative integer for the logical Depth series used by this slot. Reordering slots does not change source binding.": "Невід’ємне ціле число з відліком від нуля для логічної серії глибини, яку використовує цей слот. Зміна порядку слотів не змінює прив’язку до джерела.",
  "Zoom in": "Збільшити",
  "Zoom out": "Зменшити",
