  "a comparison cannot be bound losslessly to its source records.": "порівняння неможливо без втрат прив’язати до його вихідних записів.",
  "a feature color rule names feature instances by a pattern that the CLI record keys cannot carry.": "правило кольору ознак вказує на екземпляри ознак за виразом, який не можуть містити ключі запису CLI.",
  "a feature edit has a value that the feature override table cannot carry.": "редагування ознаки має значення, якого не може містити таблиця перевизначень ознак.",
  "a feature edit names a feature identity that no table row can carry.": "редагування ознаки вказує на ідентифікацію ознаки, яку не може містити жоден рядок таблиці.",
  "a feature edit or placement names a feature that the source does not have.": "редагування або розміщення ознаки вказує на ознаку, якої немає в джерелі.",
