  "a {mode} track slot contains text (\",\", \":\", \"@\", or \" #\") that the CLI slot grammar cannot carry.": "слот доріжки для режиму {mode} містить текст («,», «:», «@» або «#» після пробілу), який граматика слотів CLI не може передати.",
