  "location and record_location rows cannot be matched to {count} label on a cropped, reverse-complemented, or rotated record until the diagram records where it drew it. Generate the diagram again, then load the table.": "На обрізаному, зворотно-комплементарному або повернутому записі {count} підпис не можна зіставити з рядками location та record_location, доки діаграма не запише, де його намальовано. Створіть діаграму знову, потім завантажте таблицю.",
  "location and record_location rows cannot be matched to {count} labels on cropped, reverse-complemented, or rotated records until the diagram records where it drew them. Generate the diagram again, then load the table.": {"one": "На обрізаних, зворотно-комплементарних або повернутих записах {count} підпис не можна зіставити з рядками location та record_location, доки діаграма не запише, де його намальовано. Створіть діаграму знову, потім завантажте таблицю.", "few": "На обрізаних, зворотно-комплементарних або повернутих записах {count} підписи не можна зіставити з рядками location та record_location, доки діаграма не запише, де їх намальовано. Створіть діаграму знову, потім завантажте таблицю.", "many": "На обрізаних, зворотно-комплементарних або повернутих записах {count} підписів не можна зіставити з рядками location та record_location, доки діаграма не запише, де їх намальовано. Створіть діаграму знову, потім завантажте таблицю.", "other": "На обрізаному, зворотно-комплементарному або повернутому записі {count} підпису не можна зіставити з рядками location та record_location, доки діаграма не запише, де його намальовано. Створіть діаграму знову, потім завантажте таблицю."},
