  "{count} Feature visibility edit from an older Session hid every feature with the same hash, such as each copy of a duplicated record. It now applies only to the feature that was edited, so the next Generate draws the others.": "{count} редагування видимості ознаки зі старішого сеансу приховувало кожну ознаку з тим самим хешем, наприклад кожну копію дубльованого запису. Тепер воно застосовується лише до відредагованої ознаки, тому під час наступного створення інші ознаки буде намальовано.",
  "{count} Feature visibility edits from an older Session hid every feature with the same hash, such as each copy of a duplicated record. Each now applies only to the feature that was edited, so the next Generate draws the others.": {"one": "{count} редагування видимості ознак зі старішого сеансу приховувало кожну ознаку з тим самим хешем, наприклад кожну копію дубльованого запису. Тепер воно застосовується лише до відредагованої ознаки, тому під час наступного створення інші ознаки буде намальовано.", "few": "{count} редагування видимості ознак зі старішого сеансу приховували кожну ознаку з тим самим хешем, наприклад кожну копію дубльованого запису. Тепер кожне застосовується лише до відредагованої ознаки, тому під час наступного створення інші ознаки буде намальовано.", "many": "{count} редагувань видимості ознак зі старішого сеансу приховували кожну ознаку з тим самим хешем, наприклад кожну копію дубльованого запису. Тепер кожне застосовується лише до відредагованої ознаки, тому під час наступного створення інші ознаки буде намальовано.", "other": "{count} редагування видимості ознак зі старішого сеансу приховувало кожну ознаку з тим самим хешем, наприклад кожну копію дубльованого запису. Тепер воно застосовується лише до відредагованої ознаки, тому під час наступного створення інші ознаки буде намальовано."},
  "{count} LOSAT result is cached and reused when the inputs and settings match.": "У кеші {count} результат LOSAT; його використовують повторно, якщо вхідні дані й налаштування збігаються.",
  "{count} LOSAT results are cached and reused when the inputs and settings match.": {"one": "У кеші {count} результат LOSAT; його використовують повторно, якщо вхідні дані й налаштування збігаються.", "few": "У кеші {count} результати LOSAT; їх використовують повторно, якщо вхідні дані й налаштування збігаються.", "many": "У кеші {count} результатів LOSAT; їх використовують повторно, якщо вхідні дані й налаштування збігаються.", "other": "У кеші {count} результату LOSAT; його використовують повторно, якщо вхідні дані й налаштування збігаються."},
