  "{count} annotation of a selected feature that the current diagram does not draw was not exported.": "{count} анотацію вибраної ознаки, яку поточна діаграма не малює, не експортовано.",
  "{count} annotation of a selected feature was written as record=#<position> and feature_selector=hash=<feature hash>. It names the same feature only while the record order stays as drawn.": "{count} анотацію вибраної ознаки записано як record=#<position> і feature_selector=hash=<feature hash>. Вона вказує на ту саму ознаку, лише поки порядок записів залишається таким, як намальовано.",
  "{count} annotations from an older Session named a feature by hash=. Each now names that feature by its source, so it stays on the feature when the crop or orientation changes.": {"one": "{count} анотація зі старішого сеансу вказувала на ознаки через hash=. Тепер кожна вказує на ознаку через її джерело, тому залишається на ознаці, коли змінюється обрізання або орієнтація.", "few": "{count} анотації зі старішого сеансу вказували на ознаки через hash=. Тепер кожна вказує на ознаку через її джерело, тому залишається на ознаці, коли змінюється обрізання або орієнтація.", "many": "{count} анотацій зі старішого сеансу вказували на ознаки через hash=. Тепер кожна вказує на ознаку через її джерело, тому залишається на ознаці, коли змінюється обрізання або орієнтація.", "other": "Для {count} анотації зі старішого сеансу посилання на ознаку через hash= замінено посиланням через її джерело, тому прив’язка до ознаки зберігається, коли змінюється обрізання або орієнтація."},
  "{count} annotations of selected features that the current diagram does not draw were not exported.": {"one": "{count} анотацію вибраних ознак, які поточна діаграма не малює, не експортовано.", "few": "{count} анотації вибраних ознак, які поточна діаграма не малює, не експортовано.", "many": "{count} анотацій вибраних ознак, які поточна діаграма не малює, не експортовано.", "other": "{count} анотації вибраних ознак, які поточна діаграма не малює, не експортовано."},
  "{count} annotations of selected features were written as record=#<position> and feature_selector=hash=<feature hash>. They name the same features only while the record order stays as drawn.": {"one": "{count} анотацію вибраних ознак записано як record=#<position> і feature_selector=hash=<feature hash>. Вони вказують на ті самі ознаки, лише поки порядок записів залишається таким, як намальовано.", "few": "{count} анотації вибраних ознак записано як record=#<position> і feature_selector=hash=<feature hash>. Вони вказують на ті самі ознаки, лише поки порядок записів залишається таким, як намальовано.", "many": "{count} анотацій вибраних ознак записано як record=#<position> і feature_selector=hash=<feature hash>. Вони вказують на ті самі ознаки, лише поки порядок записів залишається таким, як намальовано.", "other": "{count} анотації вибраних ознак записано як record=#<position> і feature_selector=hash=<feature hash>. Вони вказують на ті самі ознаки, лише поки порядок записів залишається таким, як намальовано."},
