  "{count} hash= value from an older Session could not be renamed to the hash of a feature in its source record: the saved diagram drew a cropped or reverse-complemented record, and the value names features of several source hashes there, or the sources were not read again. hash= now names a feature by its hash in the source record, so the value may now match another feature or none.": "{count} значення hash= зі старішого сеансу не вдалося перейменувати на хеш ознаки у вихідному записі: збережена діаграма малювала обрізаний запис або запис зі зворотним комплементом, і це значення вказує там на ознаки з кількома вихідними хешами, або вихідні дані не було прочитано знову. Тепер hash= вказує на ознаку за її хешем у вихідному записі, тому значення може тепер відповідати іншій ознаці або жодній.",
  "{count} hash= values from an older Session could not be renamed to the hash of a feature in its source record: the saved diagram drew a cropped or reverse-complemented record, and the value names features of several source hashes there, or the sources were not read again. hash= now names a feature by its hash in the source record, so each may now match another feature or none.": {"one": "{count} значення hash= зі старішого сеансу не вдалося перейменувати на хеш ознаки у вихідному записі: збережена діаграма малювала обрізаний запис або запис зі зворотним комплементом, і це значення вказує там на ознаки з кількома вихідними хешами, або вихідні дані не було прочитано знову. Тепер hash= вказує на ознаку за її хешем у вихідному записі, тому значення може тепер відповідати іншій ознаці або жодній.", "few": "{count} значення hash= зі старішого сеансу не вдалося перейменувати на хеш ознаки у вихідному записі: збережена діаграма малювала обрізаний запис або запис зі зворотним комплементом, і ці значення вказують там на ознаки з кількома вихідними хешами, або вихідні дані не було прочитано знову. Тепер hash= вказує на ознаку за її хешем у вихідному записі, тому кожне значення може тепер відповідати іншій ознаці або жодній.", "many": "{count} значень hash= зі старішого сеансу не вдалося перейменувати на хеш ознаки у вихідному записі: збережена діаграма малювала обрізаний запис або запис зі зворотним комплементом, і ці значення вказують там на ознаки з кількома вихідними хешами, або вихідні дані не було прочитано знову. Тепер hash= вказує на ознаку за її хешем у вихідному записі, тому кожне значення може тепер відповідати іншій ознаці або жодній.", "other": "{count} значення hash= зі старішого сеансу не вдалося перейменувати на хеш ознаки у вихідному записі: збережена діаграма малювала обрізаний запис або запис зі зворотним комплементом, і це значення вказує там на ознаки з кількома вихідними хешами, або вихідні дані не було прочитано знову. Тепер hash= вказує на ознаку за її хешем у вихідному записі, тому значення може тепер відповідати іншій ознаці або жодній."},
